import React from "react";
import { HashRouter, Routes, Route } from "react-router-dom";
import Header from "./components/Header/Header";
import Footer from "./components/Footer/Footer";
import Home from "./pages/Home/Home";
import Blog from "./pages/Blog/Blog";
import BlogPost from "./pages/BlogPost/BlogPost";
import BlackjackGame from "./pages/BlackjackGame/BlackjackGame";
import Achievements from "./pages/Achievements/Achievements";
import FifaSchedule from "./pages/FifaSchedule/FifaSchedule";
import JsonPrettifier from "./pages/JsonPrettifier/JsonPrettifier";
import LlmChat from "./pages/LlmChat/LlmChat";
import MortgageCalculator from "./pages/MortgageCalculator/MortgageCalculator";
import NotFound from "./pages/NotFound/NotFound";
import OptionsCalculator from "./pages/OptionsCalculator/OptionsCalculator";
import PasswordGenerator from "./pages/PasswordGenerator/PasswordGenerator";
import Secret from "./pages/Secret/Secret";
import SolarSystem from "./pages/SolarSystem/SolarSystem";
import TextCompare from "./pages/TextCompare/TextCompare";
import "./App.css";

function App() {
  return (
    <HashRouter>
      <div className="app">
        <Header />
        <main className="main-content">
          <Routes>
            <Route path="/" element={<Home />} />
            <Route path="/blog" element={<Blog />} />
            <Route path="/blog/:slug" element={<BlogPost />} />
            <Route path="/achievements" element={<Achievements />} />
            <Route path="/secret" element={<Secret />} />
            <Route path="/llm-chat" element={<LlmChat />} />
            <Route path="/apps-prettifier" element={<JsonPrettifier />} />
            <Route path="/apps-text-compare" element={<TextCompare />} />
            <Route path="/apps-fifa-2026" element={<FifaSchedule />} />
            <Route path="/apps-mortgage" element={<MortgageCalculator />} />
            <Route path="/apps-options" element={<OptionsCalculator />} />
            <Route path="/apps-blackjack" element={<BlackjackGame />} />
            <Route
              path="/apps-password-generator"
              element={<PasswordGenerator />}
            />
            <Route path="/apps-solar-system" element={<SolarSystem />} />
            <Route path="*" element={<NotFound />} />
          </Routes>
        </main>
        <Footer />
      </div>
    </HashRouter>
  );
}

export default App;
