import React, { useState, useEffect, useRef } from "react";
import { Link, useLocation } from "react-router-dom";
import "./Header.css";

const weatherCodeMap = {
  0: { label: "Clear", icon: "☀️" },
  1: { label: "Mostly clear", icon: "🌤️" },
  2: { label: "Partly cloudy", icon: "⛅" },
  3: { label: "Cloudy", icon: "☁️" },
  45: { label: "Fog", icon: "🌫️" },
  48: { label: "Fog", icon: "🌫️" },
  51: { label: "Drizzle", icon: "🌦️" },
  53: { label: "Drizzle", icon: "🌦️" },
  55: { label: "Drizzle", icon: "🌦️" },
  56: { label: "Freezing drizzle", icon: "🌧️" },
  57: { label: "Freezing drizzle", icon: "🌧️" },
  61: { label: "Rain", icon: "🌧️" },
  63: { label: "Rain", icon: "🌧️" },
  65: { label: "Heavy rain", icon: "🌧️" },
  66: { label: "Freezing rain", icon: "🌧️" },
  67: { label: "Freezing rain", icon: "🌧️" },
  71: { label: "Snow", icon: "🌨️" },
  73: { label: "Snow", icon: "🌨️" },
  75: { label: "Heavy snow", icon: "❄️" },
  77: { label: "Snow grains", icon: "❄️" },
  80: { label: "Rain showers", icon: "🌦️" },
  81: { label: "Rain showers", icon: "🌦️" },
  82: { label: "Heavy rain showers", icon: "🌧️" },
  85: { label: "Snow showers", icon: "🌨️" },
  86: { label: "Snow showers", icon: "🌨️" },
  95: { label: "Thunderstorm", icon: "⛈️" },
  96: { label: "Thunderstorm with hail", icon: "⛈️" },
  99: { label: "Thunderstorm with hail", icon: "⛈️" },
};

const getWeatherCondition = (weatherCode) =>
  weatherCodeMap[weatherCode] || { label: "Current weather", icon: "◦" };

const audioSrc = `${process.env.PUBLIC_URL}/audio/waltz-in-a-minor.mp3`;
const weatherRefreshIntervalMs = 600 * 1000;
const torontoWeatherCoordinates = {
  latitude: "43.6532",
  longitude: "-79.3832",
};

function Header() {
  const [menuOpen, setMenuOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const [isAudioPlaying, setIsAudioPlaying] = useState(false);
  const audioRef = useRef(null);
  const [weather, setWeather] = useState({
    status: "loading",
    temperature: null,
    temperatureUnit: "°C",
    weatherCode: null,
    conditionLabel: "Current weather",
    conditionIcon: "◦",
  });
  const location = useLocation();

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 8);
    };
    window.addEventListener("scroll", handleScroll, { passive: true });
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  useEffect(() => {
    const audio = audioRef.current;

    return () => {
      if (audio) {
        audio.pause();
      }
    };
  }, []);

  useEffect(() => {
    let cancelled = false;
    const controller = new AbortController();

    const setUnavailable = () => {
      if (!cancelled) {
        setWeather((currentWeather) => ({
          ...currentWeather,
          status: "unavailable",
        }));
      }
    };

    const loadWeather = async () => {
      const params = new URLSearchParams({
        ...torontoWeatherCoordinates,
        current: "temperature_2m,weather_code",
      });

      try {
        const response = await fetch(
          `https://api.open-meteo.com/v1/forecast?${params.toString()}`,
          { signal: controller.signal }
        );

        if (!response.ok) {
          throw new Error("Unable to load weather");
        }

        const forecast = await response.json();
        const current = forecast.current || {};
        const currentUnits = forecast.current_units || {};

        if (
          typeof current.temperature_2m !== "number" ||
          typeof current.weather_code !== "number"
        ) {
          throw new Error("Weather response is missing current conditions");
        }

        if (!cancelled) {
          const condition = getWeatherCondition(current.weather_code);

          setWeather({
            status: "ready",
            temperature: Math.round(current.temperature_2m),
            temperatureUnit: currentUnits.temperature_2m || "°C",
            weatherCode: current.weather_code,
            conditionLabel: condition.label,
            conditionIcon: condition.icon,
          });
        }
      } catch (error) {
        if (error.name !== "AbortError") {
          setUnavailable();
        }
      }
    };

    loadWeather();
    const weatherRefreshInterval = window.setInterval(
      loadWeather,
      weatherRefreshIntervalMs
    );

    return () => {
      cancelled = true;
      window.clearInterval(weatherRefreshInterval);
      controller.abort();
    };
  }, []);

  // Close mobile menu on route change
  useEffect(() => {
    setMenuOpen(false);
  }, [location]);

  const navLinks = [
    { to: "/", label: "Home" },
    { to: "/blog", label: "Blog" },
    { to: "/achievements", label: "Work" },
  ];

  const isActive = (path) => {
    if (path === "/") return location.pathname === "/";
    return location.pathname.startsWith(path);
  };

  const renderWeather = () => {
    if (weather.status === "ready") {
      return (
        <>
          <span className="header__weather-location">Toronto</span>
          <span
            className="header__weather-icon"
            role="img"
            aria-label={weather.conditionLabel}
          >
            {weather.conditionIcon}
          </span>
          <span className="header__weather-temp">
            {weather.temperature}
            {weather.temperatureUnit}
          </span>
        </>
      );
    }

    return (
      <span className="header__weather-status">
        {weather.status === "loading"
          ? "Toronto weather"
          : "Toronto weather unavailable"}
      </span>
    );
  };

  const handleAudioToggle = async () => {
    const audio = audioRef.current;

    if (!audio) return;

    if (isAudioPlaying) {
      audio.pause();
      audio.currentTime = 0;
      setIsAudioPlaying(false);
      return;
    }

    try {
      audio.loop = true;
      await audio.play();
      setIsAudioPlaying(true);
    } catch (error) {
      setIsAudioPlaying(false);
    }
  };

  return (
    <header
      className={`header ${scrolled ? "header--scrolled" : ""}`}
      id="site-header"
    >
      <div className="header__inner container--wide">
        <div className="header__gadgets">
          <div
            className={`header__weather header__weather--${weather.status}`}
            id="header-weather"
            aria-live="polite"
            title={`${weather.conditionLabel} in Toronto`}
          >
            <span className="header__weather-content">{renderWeather()}</span>
          </div>

          <button
            type="button"
            className={`header__audio ${
              isAudioPlaying ? "header__audio--playing" : ""
            }`}
            onClick={handleAudioToggle}
            aria-label={isAudioPlaying ? "Stop audio" : "Play audio"}
            aria-pressed={isAudioPlaying}
            title={isAudioPlaying ? "Stop audio" : "Play audio"}
          >
            <span className="header__audio-icon" aria-hidden="true"></span>
          </button>

          {isAudioPlaying && (
            <span className="header__audio-title">
              Waltz in A minor, Op. posth.
            </span>
          )}

          <audio
            ref={audioRef}
            src={audioSrc}
            loop
            preload="none"
            onPause={() => setIsAudioPlaying(false)}
            onPlay={() => setIsAudioPlaying(true)}
          />
        </div>

        <nav
          className={`header__nav ${menuOpen ? "header__nav--open" : ""}`}
          id="main-nav"
          role="navigation"
          aria-label="Main navigation"
        >
          {navLinks.map((link) => (
            <Link
              key={link.to}
              to={link.to}
              className={`header__link ${
                isActive(link.to) ? "header__link--active" : ""
              }`}
              id={`nav-${link.label.toLowerCase()}`}
            >
              {link.label}
            </Link>
          ))}
        </nav>

        <button
          className={`header__hamburger ${
            menuOpen ? "header__hamburger--open" : ""
          }`}
          onClick={() => setMenuOpen(!menuOpen)}
          aria-label="Toggle menu"
          aria-expanded={menuOpen}
          id="menu-toggle"
        >
          <span></span>
          <span></span>
        </button>
      </div>
    </header>
  );
}

export default Header;
