function normalizeDegrees(degrees) {
  return ((degrees % 360) + 360) % 360;
}

function getTodayInputValue() {
  const today = new Date();
  const year = today.getFullYear();
  const month = String(today.getMonth() + 1).padStart(2, "0");
  const day = String(today.getDate()).padStart(2, "0");

  return `${year}-${month}-${day}`;
}

function getUtcInputValue(date) {
  const year = date.getUTCFullYear();
  const month = String(date.getUTCMonth() + 1).padStart(2, "0");
  const day = String(date.getUTCDate()).padStart(2, "0");

  return `${year}-${month}-${day}`;
}

function getDateFromInput(value) {
  const [year, month, day] = value.split("-").map(Number);

  if (!year || !month || !day) {
    return new Date(Date.UTC(2026, 4, 22, 12));
  }

  return new Date(Date.UTC(year, month - 1, day, 12));
}

function solveEccentricAnomaly(meanAnomalyRad, eccentricity) {
  let eccentricAnomaly =
    eccentricity < 0.8 ? meanAnomalyRad : Math.PI * Math.sign(meanAnomalyRad);

  for (let step = 0; step < 8; step += 1) {
    const delta =
      (eccentricAnomaly -
        eccentricity * Math.sin(eccentricAnomaly) -
        meanAnomalyRad) /
      (1 - eccentricity * Math.cos(eccentricAnomaly));
    eccentricAnomaly -= delta;
  }

  return eccentricAnomaly;
}

function getPositionFromMeanAnomaly(planet, meanAnomalyRad) {
  const eccentricAnomaly = solveEccentricAnomaly(
    meanAnomalyRad,
    planet.eccentricity
  );
  const orbitalX =
    planet.semiMajorAxisAU * (Math.cos(eccentricAnomaly) - planet.eccentricity);
  const orbitalY =
    planet.semiMajorAxisAU *
    Math.sqrt(1 - planet.eccentricity ** 2) *
    Math.sin(eccentricAnomaly);
  const trueAnomalyRad = Math.atan2(orbitalY, orbitalX);
  const distanceAU = Math.sqrt(orbitalX ** 2 + orbitalY ** 2);

  const ascendingNodeRad = planet.longitudeAscendingNodeDeg * DEG_TO_RAD;
  const inclinationRad = planet.inclinationDeg * DEG_TO_RAD;
  const argumentPerihelionRad =
    (planet.longitudePerihelionDeg - planet.longitudeAscendingNodeDeg) *
    DEG_TO_RAD;
  const argumentOfLatitudeRad = trueAnomalyRad + argumentPerihelionRad;

  const cosNode = Math.cos(ascendingNodeRad);
  const sinNode = Math.sin(ascendingNodeRad);
  const cosLatitude = Math.cos(argumentOfLatitudeRad);
  const sinLatitude = Math.sin(argumentOfLatitudeRad);
  const cosInclination = Math.cos(inclinationRad);
  const sinInclination = Math.sin(inclinationRad);

  const x =
    distanceAU *
    (cosNode * cosLatitude - sinNode * sinLatitude * cosInclination);
  const y =
    distanceAU *
    (sinNode * cosLatitude + cosNode * sinLatitude * cosInclination);
  const z = distanceAU * sinLatitude * sinInclination;

  return {
    x,
    y,
    z,
    distanceAU,
    longitudeDeg: normalizeDegrees(Math.atan2(y, x) * RAD_TO_DEG),
    latitudeDeg: Math.asin(z / distanceAU) * RAD_TO_DEG,
  };
}

function getPlanetPosition(planet, date) {
  const daysSinceJ2000 = (date.getTime() - J2000_UTC_MS) / DAY_MS;
  const meanLongitudeDeg = normalizeDegrees(
    planet.meanLongitudeDeg + (360 / planet.periodDays) * daysSinceJ2000
  );
  const meanAnomalyDeg = normalizeDegrees(
    meanLongitudeDeg - planet.longitudePerihelionDeg
  );

  return getPositionFromMeanAnomaly(planet, meanAnomalyDeg * DEG_TO_RAD);
}

function getVisualDistance(distanceAU, focusMode) {
  if (focusMode === "inner") {
    return distanceAU * 9.4;
  }

  return Math.sqrt(distanceAU) * 5.4;
}

function getVisualPoint(position, focusMode) {
  const visualDistance = getVisualDistance(position.distanceAU, focusMode);
  const ratio = visualDistance / position.distanceAU;

  return {
    x: position.x * ratio,
    y: position.y * ratio,
    z: position.z * ratio,
  };
}

function getDisplayedPlanets(focusMode) {
  if (focusMode === "inner") {
    return PLANETS.filter(
      (planet) => planet.semiMajorAxisAU <= INNER_PLANET_LIMIT_AU
    );
  }

  return PLANETS;
}

function getOrbitSamples(planet, focusMode, sampleCount = 180) {
  return Array.from({ length: sampleCount + 1 }, (_, index) => {
    const meanAnomalyRad = (index / sampleCount) * Math.PI * 2;
    return getVisualPoint(
      getPositionFromMeanAnomaly(planet, meanAnomalyRad),
      focusMode
    );
  });
}

function formatNumber(value, digits = 2) {
  return value.toLocaleString(undefined, {
    maximumFractionDigits: digits,
    minimumFractionDigits: digits,
  });
}

function formatPeriod(days) {
  if (days < 1000) {
    return `${formatNumber(days, 1)} days`;
  }

  return `${formatNumber(days / 365.256, 1)} years`;
}

function apply3DSelection(sceneState, selectedPlanetName) {
  if (!sceneState) return;

  PLANETS.forEach((planet) => {
    const selected = selectedPlanetName === planet.name;
    const orbitMaterial = sceneState.orbitMaterialsByName[planet.name];
    const selectionRing = sceneState.selectionRingsByName[planet.name];
    const marker = sceneState.markersByName[planet.name];

    if (orbitMaterial) {
      orbitMaterial.color.set(selected ? planet.color : 0xbdbdbd);
      orbitMaterial.opacity = selected ? 0.82 : 0.34;
    }

    if (selectionRing) {
      selectionRing.visible = selected;
    }

    if (marker) {
      marker.visible = selected;
    }
  });
}

function SolarMap2D({
  focusMode,
  onSelectPlanet,
  positionsByName,
  selectedPlanetName,
}) {
  const displayedPlanets = getDisplayedPlanets(focusMode);
  const viewBox = focusMode === "inner" ? "-18 -18 36 36" : "-33 -33 66 66";

  return (
    <div className="solar-system__map" aria-label="2D solar system map">
      <svg viewBox={viewBox} role="img">
        <title>2D solar system planet positions</title>
        <circle className="solar-system__sun-glow" cx="0" cy="0" r="1.8" />
        <circle className="solar-system__sun" cx="0" cy="0" r="0.72" />

        {displayedPlanets.map((planet) => {
          const points = getOrbitSamples(planet, focusMode)
            .map(
              (point) =>
                `${formatNumber(point.x, 3)},${formatNumber(-point.y, 3)}`
            )
            .join(" ");

          return (
            <polyline
              key={planet.name}
              className="solar-system__orbit-line"
              points={points}
            />
          );
        })}

        {displayedPlanets.map((planet) => {
          const position = positionsByName[planet.name];
          const point = getVisualPoint(position, focusMode);
          const selected = selectedPlanetName === planet.name;
          const radius = Math.max(
            0.34,
            Math.min(0.72, Math.sqrt(planet.diameterKm / 12742) * 0.34)
          );

          return (
            <g
              key={planet.name}
              className={`solar-system__planet-marker ${
                selected ? "is-selected" : ""
              }`}
              role="button"
              tabIndex="0"
              transform={`translate(${point.x} ${-point.y})`}
              onClick={() => onSelectPlanet(planet.name)}
              onKeyDown={(event) => {
                if (event.key === "Enter" || event.key === " ") {
                  onSelectPlanet(planet.name);
                }
              }}
              aria-label={`Select ${planet.name}`}
            >
              {selected && (
                <circle
                  className="solar-system__planet-selection"
                  cx="0"
                  cy="0"
                  r={radius + 0.42}
                />
              )}
              <circle r={radius} fill={planet.color} />
              <text x={radius + 0.45} y="-0.32">
                {planet.name}
              </text>
            </g>
          );
        })}
      </svg>
    </div>
  );
}

function SolarScene3D({
  focusMode,
  onSelectPlanet,
  positionsByName,
  selectedPlanetName,
}) {
  const mountRef = useRef(null);
  const sceneStateRef = useRef(null);
  const selectedPlanetNameRef = useRef(selectedPlanetName);

  useEffect(() => {
    selectedPlanetNameRef.current = selectedPlanetName;
    apply3DSelection(sceneStateRef.current, selectedPlanetName);
  }, [selectedPlanetName]);

  useEffect(() => {
    const mount = mountRef.current;
    if (!mount) return undefined;

    const displayedPlanets = getDisplayedPlanets(focusMode);
    const width = mount.clientWidth || 800;
    const height = mount.clientHeight || 520;
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(46, width / height, 0.1, 220);
    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      alpha: true,
    });
    const root = new THREE.Group();
    const clickablePlanets = [];
    const orbitMaterials = [];
    const planetMaterials = [];
    const lineMaterials = [];
    const orbitMaterialsByName = {};
    const selectionRingsByName = {};
    const markersByName = {};

    mount.textContent = "";
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    renderer.setSize(width, height);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.domElement.className = "solar-system__webgl-canvas";
    renderer.domElement.setAttribute(
      "aria-label",
      "Interactive 3D solar system scene"
    );
    mount.appendChild(renderer.domElement);

    camera.position.set(
      0,
      focusMode === "inner" ? 15 : 30,
      focusMode === "inner" ? 20 : 43
    );
    scene.add(root);
    scene.add(new THREE.AmbientLight(0xffffff, 1.6));

    const sunLight = new THREE.PointLight(0xfff1c4, 2.4, 110);
    sunLight.position.set(0, 0, 0);
    scene.add(sunLight);

    const sun = new THREE.Mesh(
      new THREE.SphereGeometry(focusMode === "inner" ? 0.62 : 0.72, 40, 24),
      new THREE.MeshStandardMaterial({
        color: 0xf4b14a,
        emissive: 0xd28b24,
        emissiveIntensity: 0.8,
        roughness: 0.45,
      })
    );
    root.add(sun);
    planetMaterials.push(sun.material);

    const grid = new THREE.GridHelper(
      focusMode === "inner" ? 34 : 64,
      focusMode === "inner" ? 17 : 32,
      0xd7d7d7,
      0xe3e3e3
    );
    grid.position.y = -0.02;
    root.add(grid);

    displayedPlanets.forEach((planet) => {
      const orbitPoints = getOrbitSamples(planet, focusMode, 220).map(
        (point) =>
          new THREE.Vector3(
            point.x,
            point.z * THREE_VERTICAL_EXAGGERATION,
            -point.y
          )
      );
      const orbitGeometry = new THREE.BufferGeometry().setFromPoints(
        orbitPoints
      );
      const orbitMaterial = new THREE.LineBasicMaterial({
        color: 0xbdbdbd,
        opacity: 0.34,
        transparent: true,
      });
      const orbit = new THREE.Line(orbitGeometry, orbitMaterial);
      root.add(orbit);
      orbitMaterials.push(orbitMaterial);
      orbitMaterialsByName[planet.name] = orbitMaterial;

      const position = getVisualPoint(positionsByName[planet.name], focusMode);
      const planetRadius = Math.max(
        0.16,
        Math.min(0.64, Math.sqrt(planet.diameterKm / 12742) * 0.24)
      );
      const planetMaterial = new THREE.MeshStandardMaterial({
        color: new THREE.Color(planet.color),
        roughness: 0.56,
        metalness: 0.04,
      });
      const mesh = new THREE.Mesh(
        new THREE.SphereGeometry(planetRadius, 36, 20),
        planetMaterial
      );
      mesh.position.set(
        position.x,
        position.z * THREE_VERTICAL_EXAGGERATION,
        -position.y
      );
      mesh.userData.name = planet.name;
      clickablePlanets.push(mesh);
      root.add(mesh);
      planetMaterials.push(planetMaterial);

      if (planet.name === "Saturn") {
        const ring = new THREE.Mesh(
          new THREE.TorusGeometry(planetRadius * 1.75, 0.025, 10, 56),
          new THREE.MeshBasicMaterial({
            color: 0xb8a878,
            opacity: 0.72,
            transparent: true,
          })
        );
        ring.rotation.x = Math.PI * 0.58;
        mesh.add(ring);
        planetMaterials.push(ring.material);
      }

      const selection = new THREE.Mesh(
        new THREE.TorusGeometry(planetRadius + 0.2, 0.02, 8, 48),
        new THREE.MeshBasicMaterial({
          color: new THREE.Color(planet.color),
          opacity: 0.9,
          transparent: true,
        })
      );
      selection.rotation.x = Math.PI / 2;
      selection.visible = false;
      mesh.add(selection);
      planetMaterials.push(selection.material);
      selectionRingsByName[planet.name] = selection;

      const markerGeometry = new THREE.BufferGeometry().setFromPoints([
        new THREE.Vector3(mesh.position.x, 0, mesh.position.z),
        new THREE.Vector3(mesh.position.x, mesh.position.y, mesh.position.z),
      ]);
      const markerMaterial = new THREE.LineBasicMaterial({
        color: new THREE.Color(planet.color),
        opacity: 0.36,
        transparent: true,
      });
      const marker = new THREE.Line(markerGeometry, markerMaterial);
      marker.visible = false;
      root.add(marker);
      lineMaterials.push(markerMaterial);
      markersByName[planet.name] = marker;
    });

    const sceneState = {
      orbitMaterialsByName,
      selectionRingsByName,
      markersByName,
    };
    sceneStateRef.current = sceneState;
    apply3DSelection(sceneState, selectedPlanetNameRef.current);

    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.autoRotate = true;
    controls.autoRotateSpeed = 0.34;
    controls.minDistance = focusMode === "inner" ? 8 : 18;
    controls.maxDistance = focusMode === "inner" ? 42 : 90;
    controls.target.set(0, 0, 0);

    const raycaster = new THREE.Raycaster();
    const pointer = new THREE.Vector2();
    const handlePointerDown = (event) => {
      const rect = renderer.domElement.getBoundingClientRect();
      pointer.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
      pointer.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
      raycaster.setFromCamera(pointer, camera);

      const intersects = raycaster.intersectObjects(clickablePlanets, false);
      if (intersects.length > 0) {
        onSelectPlanet(intersects[0].object.userData.name);
      }
    };

    renderer.domElement.addEventListener("pointerdown", handlePointerDown);

    const resize = () => {
      const nextWidth = mount.clientWidth || width;
      const nextHeight = mount.clientHeight || height;
      renderer.setSize(nextWidth, nextHeight);
      camera.aspect = nextWidth / nextHeight;
      camera.updateProjectionMatrix();
    };
    const resizeObserver =
      typeof ResizeObserver !== "undefined" ? new ResizeObserver(resize) : null;

    if (resizeObserver) {
      resizeObserver.observe(mount);
    } else {
      window.addEventListener("resize", resize);
    }

    let frameId = 0;
    const animate = () => {
      sun.rotation.y += 0.006;
      controls.update();
      renderer.render(scene, camera);
      frameId = window.requestAnimationFrame(animate);
    };
    animate();

    return () => {
      window.cancelAnimationFrame(frameId);
      renderer.domElement.removeEventListener("pointerdown", handlePointerDown);
      controls.dispose();
      if (resizeObserver) {
        resizeObserver.disconnect();
      } else {
        window.removeEventListener("resize", resize);
      }

      root.traverse((object) => {
        if (object.geometry) object.geometry.dispose();
      });
      orbitMaterials.forEach((material) => material.dispose());
      planetMaterials.forEach((material) => material.dispose());
      lineMaterials.forEach((material) => material.dispose());
      renderer.dispose();
      renderer.forceContextLoss();

      if (renderer.domElement.parentNode === mount) {
        mount.removeChild(renderer.domElement);
      }

      if (sceneStateRef.current === sceneState) {
        sceneStateRef.current = null;
      }
    };
  }, [focusMode, onSelectPlanet, positionsByName]);

  return (
    <div
      ref={mountRef}
      className="solar-system__scene"
      aria-label="3D solar system view"
    />
  );
}

function SolarSystem() {
  const [dateInput, setDateInput] = useState(getTodayInputValue);
  const [viewMode, setViewMode] = useState("2d");
  const [focusMode, setFocusMode] = useState("full");
  const [selectedPlanetName, setSelectedPlanetName] = useState("Earth");

  useEffect(() => {
    document.title = "Solar System - Xuan Cao";
  }, []);

  const selectedPlanet = PLANETS.find(
    (planet) => planet.name === selectedPlanetName
  );

  useEffect(() => {
    if (
      focusMode === "inner" &&
      selectedPlanet &&
      selectedPlanet.semiMajorAxisAU > INNER_PLANET_LIMIT_AU
    ) {
      setSelectedPlanetName("Earth");
    }
  }, [focusMode, selectedPlanet]);

  const mapDate = useMemo(() => getDateFromInput(dateInput), [dateInput]);

  const positionsByName = useMemo(() => {
    return PLANETS.reduce((positions, planet) => {
      positions[planet.name] = getPlanetPosition(planet, mapDate);
      return positions;
    }, {});
  }, [mapDate]);

  const selectedPosition = positionsByName[selectedPlanetName];
  const displayedDate = new Intl.DateTimeFormat(undefined, {
    month: "short",
    day: "numeric",
    year: "numeric",
    timeZone: "UTC",
  }).format(mapDate);

  const displayedPlanets = getDisplayedPlanets(focusMode);

  const handleSelectPlanet = useCallback(
    (planetName) => {
      const nextPlanet = PLANETS.find((planet) => planet.name === planetName);
      if (
        nextPlanet &&
        focusMode === "inner" &&
        nextPlanet.semiMajorAxisAU > INNER_PLANET_LIMIT_AU
      ) {
        setFocusMode("full");
      }

      setSelectedPlanetName(planetName);
    },
    [focusMode]
  );

  const shiftDate = (days) => {
    const nextDate = getDateFromInput(dateInput);
    nextDate.setUTCDate(nextDate.getUTCDate() + days);
    setDateInput(getUtcInputValue(nextDate));
  };

  return (
    <div className="solar-system">
      <div className="container container--wide">
        <header className="solar-system__header fade-in">
          <div>
            <p className="section-label">Interactive model</p>
            <h1 className="page-title">Solar System</h1>
            <p className="page-subtitle">
              Explore calculation-based, approximate planet locations around the
              Sun. Positions are educational estimates, not accurate ephemeris data.
            </p>
          </div>
          <div className="solar-system__status" role="status">
            <strong>{displayedDate}</strong>
            <span>
              {focusMode === "inner" ? "Inner planet zoom" : "Full system"} ·{" "}
              {displayedPlanets.length} planets shown
            </span>
          </div>
        </header>

        <section className="solar-system__toolbar fade-in fade-in--delay-1">
          <div className="solar-system__control-group">
            <span>View</span>
            <div className="solar-system__segmented">
              <button
                type="button"
                className={viewMode === "2d" ? "is-active" : ""}
                onClick={() => setViewMode("2d")}
              >
                2D Map
              </button>
              <button
                type="button"
                className={viewMode === "3d" ? "is-active" : ""}
                onClick={() => setViewMode("3d")}
              >
                3D Orbit
              </button>
            </div>
          </div>

          <div className="solar-system__control-group">
            <span>Scale</span>
            <div className="solar-system__segmented">
              <button
                type="button"
                className={focusMode === "full" ? "is-active" : ""}
                onClick={() => setFocusMode("full")}
              >
                Full
              </button>
              <button
                type="button"
                className={focusMode === "inner" ? "is-active" : ""}
                onClick={() => setFocusMode("inner")}
              >
                Inner
              </button>
            </div>
          </div>

          <div className="solar-system__date-control">
            <button type="button" onClick={() => shiftDate(-30)}>
              -30d
            </button>
            <input
              type="date"
              value={dateInput}
              onChange={(event) => setDateInput(event.target.value)}
              aria-label="Solar system map date"
            />
            <button
              type="button"
              onClick={() => setDateInput(getTodayInputValue())}
            >
              Today
            </button>
            <button type="button" onClick={() => shiftDate(30)}>
              +30d
            </button>
          </div>
        </section>

        <section className="solar-system__workspace fade-in fade-in--delay-2">
          <div className="solar-system__viewer">
            {viewMode === "2d" ? (
              <SolarMap2D
                focusMode={focusMode}
                onSelectPlanet={handleSelectPlanet}
                positionsByName={positionsByName}
                selectedPlanetName={selectedPlanetName}
              />
            ) : (
              <SolarScene3D
                focusMode={focusMode}
                onSelectPlanet={handleSelectPlanet}
                positionsByName={positionsByName}
                selectedPlanetName={selectedPlanetName}
              />
            )}

            <section className="solar-system__basic-info">
              <p>{selectedPlanet.info.overview}</p>
            </section>
          </div>

          <aside className="solar-system__sidebar">
            <div className="solar-system__panel-header">
              <div>
                <h2>{selectedPlanet.name}</h2>
                <p>{selectedPlanet.tagline}</p>
              </div>
              <span
                className="solar-system__planet-swatch"
                style={{ backgroundColor: selectedPlanet.color }}
                aria-hidden="true"
              />
            </div>

            <dl className="solar-system__facts">
              <div>
                <dt>Distance from Sun</dt>
                <dd>{formatNumber(selectedPosition.distanceAU, 3)} AU</dd>
              </div>
              <div>
                <dt>Heliocentric longitude</dt>
                <dd>{formatNumber(selectedPosition.longitudeDeg, 1)}°</dd>
              </div>
              <div>
                <dt>Ecliptic latitude</dt>
                <dd>{formatNumber(selectedPosition.latitudeDeg, 2)}°</dd>
              </div>
              <div>
                <dt>Orbit period</dt>
                <dd>{formatPeriod(selectedPlanet.periodDays)}</dd>
              </div>
              <div>
                <dt>Average orbital speed</dt>
                <dd>{formatNumber(selectedPlanet.averageSpeedKmS, 1)} km/s</dd>
              </div>
            </dl>

            <div className="solar-system__planet-list">
              {PLANETS.map((planet) => (
                <button
                  key={planet.name}
                  type="button"
                  className={
                    selectedPlanetName === planet.name ? "is-active" : ""
                  }
                  onClick={() => handleSelectPlanet(planet.name)}
                >
                  <span
                    style={{ backgroundColor: planet.color }}
                    aria-hidden="true"
                  />
                  {planet.name}
                </button>
              ))}
            </div>
          </aside>
        </section>

        <section className="solar-system__metrics fade-in fade-in--delay-3">
          <div>
            <span>Date</span>
            <strong>{displayedDate}</strong>
          </div>
          <div>
            <span>Selected planet</span>
            <strong>{selectedPlanet.name}</strong>
          </div>
          <div>
            <span>Position model</span>
            <strong>Simplified heliocentric</strong>
          </div>
          <div>
            <span>3D note</span>
            <strong>Inclination exaggerated</strong>
          </div>
        </section>
      </div>
    </div>
  );
}

export default SolarSystem;
