import React, { useEffect, useMemo, useState } from "react";
import "./MortgageCalculator.css";

const MONTHS = [
  "Jan",
  "Feb",
  "Mar",
  "Apr",
  "May",
  "Jun",
  "Jul",
  "Aug",
  "Sep",
  "Oct",
  "Nov",
  "Dec",
];

const DEFAULT_INPUTS = {
  homePrice: 650000,
  downPayment: 130000,
  downPaymentPercent: 20,
  loanTermYears: 25,
  interestRate: 5.25,
  startMonth: 4,
  startYear: 2026,
  propertyTax: 5200,
  homeInsurance: 1800,
  pmiInsurance: 0,
  hoaFee: 0,
  otherCosts: 1200,
  annualCostIncrease: 2,
  extraMonthly: 0,
  annualLumpSum: 5000,
  oneTimePayment: 10000,
  oneTimeMonth: 0,
  oneTimeYear: 2027,
};

function toNumber(value, fallback = 0) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function currency(value, maximumFractionDigits = 0) {
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    maximumFractionDigits,
  }).format(value);
}

function number(value, maximumFractionDigits = 2) {
  return new Intl.NumberFormat("en-US", {
    maximumFractionDigits,
  }).format(value);
}

function addMonths(month, year, offset) {
  const total = month + offset;
  return {
    month: ((total % 12) + 12) % 12,
    year: year + Math.floor(total / 12),
  };
}

function monthLabel(month, year) {
  return `${MONTHS[month]} ${year}`;
}

function paymentFormula(principal, annualRate, periodsPerYear, totalPeriods) {
  if (principal <= 0) return 0;
  const rate = annualRate / 100 / periodsPerYear;
  if (rate === 0) return principal / totalPeriods;

  return (principal * rate) / (1 - Math.pow(1 + rate, -totalPeriods));
}

function buildCosts(inputs, yearIndex) {
  const increase = Math.pow(
    1 + Math.max(toNumber(inputs.annualCostIncrease), 0) / 100,
    yearIndex
  );

  return {
    tax: Math.max(toNumber(inputs.propertyTax), 0) * increase,
    insurance: Math.max(toNumber(inputs.homeInsurance), 0) * increase,
    pmi: Math.max(toNumber(inputs.pmiInsurance), 0) * increase,
    hoa: Math.max(toNumber(inputs.hoaFee), 0) * increase,
    other: Math.max(toNumber(inputs.otherCosts), 0) * increase,
  };
}

function simulateMortgage(inputs, strategy) {
  const homePrice = Math.max(toNumber(inputs.homePrice), 0);
  const downPayment = Math.max(toNumber(inputs.downPayment), 0);
  const principal = Math.max(homePrice - downPayment, 0);
  const years = Math.max(toNumber(inputs.loanTermYears), 1);
  const annualRate = Math.max(toNumber(inputs.interestRate), 0);
  const startMonth = Math.max(
    Math.min(Math.round(toNumber(inputs.startMonth)), 11),
    0
  );
  const startYear = Math.max(Math.round(toNumber(inputs.startYear)), 1900);
  const monthlyPayment = paymentFormula(principal, annualRate, 12, years * 12);
  const isBiweekly = strategy.frequency === "biweekly";
  const periodsPerYear = isBiweekly ? 26 : 12;
  const periodRate = annualRate / 100 / periodsPerYear;
  const scheduledPayment = isBiweekly ? monthlyPayment / 2 : monthlyPayment;
  const maximumPeriods = years * periodsPerYear;
  const annualLumpSum = strategy.annualLumpSum
    ? Math.max(toNumber(inputs.annualLumpSum), 0)
    : 0;
  const extraMonthly = strategy.extraMonthly
    ? Math.max(toNumber(inputs.extraMonthly), 0)
    : 0;
  const oneTimePayment = strategy.oneTimePayment
    ? Math.max(toNumber(inputs.oneTimePayment), 0)
    : 0;
  const oneTimeMonth = Math.max(
    Math.min(Math.round(toNumber(inputs.oneTimeMonth)), 11),
    0
  );
  const oneTimeYear = Math.max(Math.round(toNumber(inputs.oneTimeYear)), 1900);

  let balance = principal;
  let totalInterest = 0;
  let totalPrincipal = 0;
  let totalExtra = 0;
  let totalPaid = 0;
  let oneTimeApplied = false;
  const monthlyRows = [];
  const yearlyRows = [];

  for (
    let period = 0;
    period < maximumPeriods && balance > 0.005;
    period += 1
  ) {
    const monthOffset = isBiweekly
      ? Math.floor((period * 12) / periodsPerYear)
      : period;
    const date = addMonths(startMonth, startYear, monthOffset);
    const isFirstPaymentOfLoanYear = isBiweekly
      ? period % periodsPerYear === 0
      : period % 12 === 0;
    const monthlyExtraForPeriod = isBiweekly
      ? (extraMonthly * 12) / 26
      : extraMonthly;
    const oneTimeExtra =
      !oneTimeApplied &&
      oneTimePayment > 0 &&
      date.month === oneTimeMonth &&
      date.year === oneTimeYear
        ? oneTimePayment
        : 0;
    const annualExtra = isFirstPaymentOfLoanYear ? annualLumpSum : 0;
    const interest = balance * periodRate;
    const desiredPrincipal = Math.max(
      scheduledPayment +
        monthlyExtraForPeriod +
        annualExtra +
        oneTimeExtra -
        interest,
      0
    );
    const principalPaid = Math.min(balance, desiredPrincipal);
    const actualExtra = Math.max(
      principalPaid -
        Math.max(Math.min(scheduledPayment - interest, balance), 0),
      0
    );
    const payment = interest + principalPaid;

    if (oneTimeExtra > 0) {
      oneTimeApplied = true;
    }

    balance = Math.max(balance - principalPaid, 0);
    totalInterest += interest;
    totalPrincipal += principalPaid;
    totalExtra += actualExtra;
    totalPaid += payment;

    const monthKey = `${date.year}-${date.month}`;
    const lastRow = monthlyRows[monthlyRows.length - 1];

    if (isBiweekly && lastRow && lastRow.key === monthKey) {
      lastRow.payment += payment;
      lastRow.principal += principalPaid;
      lastRow.interest += interest;
      lastRow.extra += actualExtra;
      lastRow.balance = balance;
    } else {
      monthlyRows.push({
        key: monthKey,
        index: monthlyRows.length + 1,
        date: monthLabel(date.month, date.year),
        payment,
        principal: principalPaid,
        interest,
        extra: actualExtra,
        balance,
      });
    }
  }

  monthlyRows.forEach((row) => {
    const yearIndex = Math.floor((row.index - 1) / 12);
    const costs = buildCosts(inputs, yearIndex);
    const monthlyCosts =
      (costs.tax + costs.insurance + costs.pmi + costs.hoa + costs.other) / 12;
    const currentYear = yearlyRows[yearIndex] || {
      year: yearIndex + 1,
      label: `Year ${yearIndex + 1}`,
      payment: 0,
      principal: 0,
      interest: 0,
      extra: 0,
      costs: 0,
      balance: row.balance,
    };

    row.costs = monthlyCosts;
    row.outOfPocket = row.payment + monthlyCosts;
    currentYear.payment += row.payment;
    currentYear.principal += row.principal;
    currentYear.interest += row.interest;
    currentYear.extra += row.extra;
    currentYear.costs += monthlyCosts;
    currentYear.balance = row.balance;
    yearlyRows[yearIndex] = currentYear;
  });

  const payoffMonths = monthlyRows.length;
  const payoffRow = monthlyRows[monthlyRows.length - 1];
  const totalCosts = yearlyRows.reduce((sum, row) => sum + row.costs, 0);

  return {
    strategy,
    principal,
    downPayment,
    monthlyPayment,
    scheduledPayment,
    payoffMonths,
    payoffYears: payoffMonths / 12,
    payoffDate: payoffRow ? payoffRow.date : monthLabel(startMonth, startYear),
    totalInterest,
    totalPrincipal,
    totalExtra,
    totalPaid,
    totalCosts,
    monthlyRows,
    yearlyRows,
  };
}

function Metric({ label, value, tone }) {
  return (
    <div
      className={`mortgage-app__metric ${
        tone ? `mortgage-app__metric--${tone}` : ""
      }`}
    >
      <span>{label}</span>
      <strong>{value}</strong>
    </div>
  );
}

function MortgageCalculator() {
  const [inputs, setInputs] = useState(DEFAULT_INPUTS);
  const [scheduleView, setScheduleView] = useState("yearly");
  const [activeStrategyKey, setActiveStrategyKey] = useState("standard");
  const [downPaymentMode, setDownPaymentMode] = useState("fixed");

  useEffect(() => {
    document.title = "Mortgage Calculator — Xuan Cao";
  }, []);

  const strategies = useMemo(
    () => [
      {
        key: "standard",
        name: "Monthly",
        frequency: "monthly",
        extraMonthly: false,
        annualLumpSum: false,
        oneTimePayment: false,
      },
      {
        key: "monthly-extra",
        name: "Monthly + extra",
        frequency: "monthly",
        extraMonthly: true,
        annualLumpSum: true,
        oneTimePayment: true,
      },
      {
        key: "biweekly",
        name: "Biweekly",
        frequency: "biweekly",
        extraMonthly: false,
        annualLumpSum: false,
        oneTimePayment: false,
      },
      {
        key: "biweekly-extra",
        name: "Biweekly + extra",
        frequency: "biweekly",
        extraMonthly: true,
        annualLumpSum: true,
        oneTimePayment: true,
      },
    ],
    []
  );

  const results = useMemo(
    () => strategies.map((strategy) => simulateMortgage(inputs, strategy)),
    [inputs, strategies]
  );
  const baseResult = results[0];
  const activeResult =
    results.find((result) => result.strategy.key === activeStrategyKey) ||
    baseResult;
  const scheduleRows =
    scheduleView === "yearly"
      ? activeResult.yearlyRows
      : activeResult.monthlyRows;
  const monthlyCosts =
    baseResult.yearlyRows.length > 0 ? baseResult.yearlyRows[0].costs / 12 : 0;

  const updateInput = (key, value) => {
    setInputs((current) => {
      const updated = { ...current, [key]: value };

      // Sync down payment when home price or percentage changes
      if (key === "homePrice" && downPaymentMode === "percentage") {
        updated.downPayment =
          (toNumber(value) * toNumber(current.downPaymentPercent)) / 100;
      } else if (
        key === "downPaymentPercent" &&
        downPaymentMode === "percentage"
      ) {
        updated.downPayment =
          (toNumber(current.homePrice) * toNumber(value)) / 100;
      } else if (key === "downPayment" && downPaymentMode === "fixed") {
        // Update percentage based on fixed amount
        updated.downPaymentPercent =
          toNumber(current.homePrice) > 0
            ? (toNumber(value) / toNumber(current.homePrice)) * 100
            : 0;
      }

      return updated;
    });
  };

  const toggleDownPaymentMode = () => {
    const newMode = downPaymentMode === "fixed" ? "percentage" : "fixed";
    setDownPaymentMode(newMode);

    if (newMode === "percentage") {
      // Switching to percentage: calculate percentage from current fixed amount
      const percent =
        toNumber(inputs.homePrice) > 0
          ? (toNumber(inputs.downPayment) / toNumber(inputs.homePrice)) * 100
          : 20;
      updateInput("downPaymentPercent", percent);
    } else {
      // Switching to fixed: calculate fixed amount from current percentage
      const fixed =
        (toNumber(inputs.homePrice) * toNumber(inputs.downPaymentPercent)) /
        100;
      updateInput("downPayment", fixed);
    }
  };

  return (
    <div className="mortgage-app">
      <div className="container container--wide">
        <header className="mortgage-app__header fade-in">
          <div>
            <p className="section-label">Interactive tool</p>
            <h1 className="page-title">Mortgage Calculator</h1>
            <p className="page-subtitle">
              Estimate monthly payments, ownership costs, payoff time, and
              interest savings across payment strategies.
            </p>
          </div>
          <div className="mortgage-app__note" role="note">
            For planning reference only. Mortgage terms, compounding, fees,
            prepayment rules, taxes, insurance, and lender calculations can
            vary.
          </div>
        </header>

        <section className="mortgage-app__workspace fade-in fade-in--delay-1">
          <form className="mortgage-app__panel" aria-label="Mortgage inputs">
            <div className="mortgage-app__panel-header">
              <h2>Loan Details</h2>
              <p>{currency(baseResult.principal)} financed</p>
            </div>
            <div className="mortgage-app__input-grid">
              <label>
                <span>Home price</span>
                <input
                  type="number"
                  min="0"
                  step="1000"
                  value={inputs.homePrice}
                  onChange={(event) =>
                    updateInput("homePrice", event.target.value)
                  }
                />
              </label>
              <div className="mortgage-app__field">
                <div className="mortgage-app__label-row">
                  <label htmlFor="down-payment-input">Down payment</label>
                  <button
                    type="button"
                    className="mortgage-app__unit-toggle"
                    onClick={toggleDownPaymentMode}
                    aria-label={`Switch down payment to ${
                      downPaymentMode === "fixed"
                        ? "percentage"
                        : "fixed amount"
                    }`}
                    title={`Switch to ${downPaymentMode === "fixed" ? "percentage" : "fixed amount"}`}
                  >
                    {downPaymentMode === "fixed" ? "$" : "%"}
                  </button>
                </div>
                <input
                  id="down-payment-input"
                  type="number"
                  min="0"
                  step={downPaymentMode === "fixed" ? "1000" : "0.1"}
                  value={
                    downPaymentMode === "fixed"
                      ? inputs.downPayment
                      : inputs.downPaymentPercent
                  }
                  onChange={(event) =>
                    updateInput(
                      downPaymentMode === "fixed"
                        ? "downPayment"
                        : "downPaymentPercent",
                      event.target.value
                    )
                  }
                />
              </div>
              <label>
                <span>Loan term (years)</span>
                <input
                  type="number"
                  min="1"
                  step="1"
                  value={inputs.loanTermYears}
                  onChange={(event) =>
                    updateInput("loanTermYears", event.target.value)
                  }
                />
              </label>
              <label>
                <span>Interest rate (%)</span>
                <input
                  type="number"
                  min="0"
                  step="0.01"
                  value={inputs.interestRate}
                  onChange={(event) =>
                    updateInput("interestRate", event.target.value)
                  }
                />
              </label>
              <label>
                <span>Start month</span>
                <select
                  value={inputs.startMonth}
                  onChange={(event) =>
                    updateInput("startMonth", event.target.value)
                  }
                >
                  {MONTHS.map((month, index) => (
                    <option key={month} value={index}>
                      {month}
                    </option>
                  ))}
                </select>
              </label>
              <label>
                <span>Start year</span>
                <input
                  type="number"
                  min="1900"
                  step="1"
                  value={inputs.startYear}
                  onChange={(event) =>
                    updateInput("startYear", event.target.value)
                  }
                />
              </label>
            </div>

            <hr className="mortgage-app__rule" />

            <div className="mortgage-app__panel-header">
              <h2>Taxes and Costs</h2>
              <p>{currency(monthlyCosts)} monthly estimate</p>
            </div>
            <div className="mortgage-app__input-grid">
              <label>
                <span>Property tax / year</span>
                <input
                  type="number"
                  min="0"
                  step="100"
                  value={inputs.propertyTax}
                  onChange={(event) =>
                    updateInput("propertyTax", event.target.value)
                  }
                />
              </label>
              <label>
                <span>Home insurance / year</span>
                <input
                  type="number"
                  min="0"
                  step="100"
                  value={inputs.homeInsurance}
                  onChange={(event) =>
                    updateInput("homeInsurance", event.target.value)
                  }
                />
              </label>
              <label>
                <span>PMI / year</span>
                <input
                  type="number"
                  min="0"
                  step="100"
                  value={inputs.pmiInsurance}
                  onChange={(event) =>
                    updateInput("pmiInsurance", event.target.value)
                  }
                />
              </label>
              <label>
                <span>HOA / year</span>
                <input
                  type="number"
                  min="0"
                  step="100"
                  value={inputs.hoaFee}
                  onChange={(event) =>
                    updateInput("hoaFee", event.target.value)
                  }
                />
              </label>
              <label>
                <span>Other costs / year</span>
                <input
                  type="number"
                  min="0"
                  step="100"
                  value={inputs.otherCosts}
                  onChange={(event) =>
                    updateInput("otherCosts", event.target.value)
                  }
                />
              </label>
              <label>
                <span>Annual cost increase (%)</span>
                <input
                  type="number"
                  min="0"
                  step="0.1"
                  value={inputs.annualCostIncrease}
                  onChange={(event) =>
                    updateInput("annualCostIncrease", event.target.value)
                  }
                />
              </label>
            </div>

            <hr className="mortgage-app__rule" />

            <div className="mortgage-app__panel-header">
              <h2>Extra Payments</h2>
              <p>Compared below</p>
            </div>
            <div className="mortgage-app__input-grid">
              <label>
                <span>Extra monthly</span>
                <input
                  type="number"
                  min="0"
                  step="50"
                  value={inputs.extraMonthly}
                  onChange={(event) =>
                    updateInput("extraMonthly", event.target.value)
                  }
                />
              </label>
              <label>
                <span>Annual lump sum</span>
                <input
                  type="number"
                  min="0"
                  step="500"
                  value={inputs.annualLumpSum}
                  onChange={(event) =>
                    updateInput("annualLumpSum", event.target.value)
                  }
                />
              </label>
              <label>
                <span>One-time payment</span>
                <input
                  type="number"
                  min="0"
                  step="500"
                  value={inputs.oneTimePayment}
                  onChange={(event) =>
                    updateInput("oneTimePayment", event.target.value)
                  }
                />
              </label>
              <label>
                <span>One-time month</span>
                <select
                  value={inputs.oneTimeMonth}
                  onChange={(event) =>
                    updateInput("oneTimeMonth", event.target.value)
                  }
                >
                  {MONTHS.map((month, index) => (
                    <option key={month} value={index}>
                      {month}
                    </option>
                  ))}
                </select>
              </label>
              <label>
                <span>One-time year</span>
                <input
                  type="number"
                  min="1900"
                  step="1"
                  value={inputs.oneTimeYear}
                  onChange={(event) =>
                    updateInput("oneTimeYear", event.target.value)
                  }
                />
              </label>
            </div>
          </form>

          <div className="mortgage-app__results">
            <section className="mortgage-app__panel">
              <div className="mortgage-app__panel-header">
                <h2>Monthly Payment</h2>
                <p>Principal and interest</p>
              </div>
              <div className="mortgage-app__hero-number">
                {currency(baseResult.monthlyPayment, 2)}
                <span>
                  {currency(baseResult.monthlyPayment + monthlyCosts, 2)} with
                  estimated monthly taxes and costs
                </span>
              </div>
              <div className="mortgage-app__metrics">
                <Metric
                  label="Loan amount"
                  value={currency(baseResult.principal)}
                />
                <Metric
                  label="Down payment"
                  value={currency(baseResult.downPayment)}
                />
                <Metric
                  label="Total interest"
                  value={currency(baseResult.totalInterest)}
                />
                <Metric label="Payoff date" value={baseResult.payoffDate} />
              </div>
            </section>

            <section className="mortgage-app__panel">
              <div className="mortgage-app__panel-header">
                <h2>Strategy Comparison</h2>
                <p>Click a row to show schedule</p>
              </div>
              <div className="mortgage-app__strategy-list">
                {results.map((result) => {
                  const interestSaved =
                    baseResult.totalInterest - result.totalInterest;
                  const monthsSaved =
                    baseResult.payoffMonths - result.payoffMonths;

                  return (
                    <button
                      type="button"
                      key={result.strategy.key}
                      className={
                        activeStrategyKey === result.strategy.key
                          ? "is-active"
                          : ""
                      }
                      onClick={() => setActiveStrategyKey(result.strategy.key)}
                    >
                      <span>
                        <strong>{result.strategy.name}</strong>
                        <small>
                          Payoff {result.payoffDate} ·{" "}
                          {number(result.payoffYears)} yrs
                        </small>
                      </span>
                      <span>
                        <strong>{currency(interestSaved)}</strong>
                        <small>{monthsSaved} months saved</small>
                      </span>
                    </button>
                  );
                })}
              </div>
            </section>

            <section className="mortgage-app__panel">
              <div className="mortgage-app__panel-header">
                <h2>Selected Strategy</h2>
                <p>{activeResult.strategy.name}</p>
              </div>
              <div className="mortgage-app__metrics mortgage-app__metrics--three">
                <Metric
                  label="Payment cadence"
                  value={
                    activeResult.strategy.frequency === "biweekly"
                      ? `${currency(activeResult.scheduledPayment, 2)} / 2 weeks`
                      : `${currency(activeResult.scheduledPayment, 2)} / month`
                  }
                />
                <Metric
                  label="Interest saved"
                  value={currency(
                    baseResult.totalInterest - activeResult.totalInterest
                  )}
                  tone="positive"
                />
                <Metric
                  label="Extra principal"
                  value={currency(activeResult.totalExtra)}
                  tone="positive"
                />
              </div>
            </section>
          </div>
        </section>

        <section className="mortgage-app__panel mortgage-app__schedule fade-in fade-in--delay-2">
          <div className="mortgage-app__panel-header">
            <div>
              <h2>Amortization Schedule</h2>
              <p>{activeResult.strategy.name}</p>
            </div>
            <div className="mortgage-app__segmented" aria-label="Schedule view">
              <button
                type="button"
                className={scheduleView === "yearly" ? "is-active" : ""}
                onClick={() => setScheduleView("yearly")}
              >
                Yearly
              </button>
              <button
                type="button"
                className={scheduleView === "monthly" ? "is-active" : ""}
                onClick={() => setScheduleView("monthly")}
              >
                Monthly
              </button>
            </div>
          </div>

          <div className="mortgage-app__table-wrap">
            <table className="mortgage-app__table">
              <thead>
                <tr>
                  <th>{scheduleView === "yearly" ? "Year" : "Month"}</th>
                  <th>Payment</th>
                  <th>Principal</th>
                  <th>Interest</th>
                  <th>Extra</th>
                  <th>Costs</th>
                  <th>Ending Balance</th>
                </tr>
              </thead>
              <tbody>
                {scheduleRows.map((row) => (
                  <tr key={scheduleView === "yearly" ? row.year : row.key}>
                    <td>{scheduleView === "yearly" ? row.label : row.date}</td>
                    <td>{currency(row.payment)}</td>
                    <td>{currency(row.principal)}</td>
                    <td>{currency(row.interest)}</td>
                    <td>{currency(row.extra)}</td>
                    <td>{currency(row.costs)}</td>
                    <td>{currency(row.balance)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </section>
      </div>
    </div>
  );
}

export default MortgageCalculator;
