import React, { useEffect, useMemo, useState } from "react";
import "./BlackjackGame.css";

const STORAGE_KEY = "blackjack-game-v1";
const MAX_SPLIT_HANDS = 4;
const MIN_CARDS_TO_START_ROUND = 4;
const DEFAULT_RESHUFFLE_STRATEGY = "none";

const DEFAULT_SETUP = {
  initialBalance: 5000,
  deckCount: 4,
  stakeSizes: "100, 200, 500, 1000",
  stakeSize: 100,
  stakeUnits: 1,
  reshuffleStrategy: DEFAULT_RESHUFFLE_STRATEGY,
};

const RESHUFFLE_STRATEGIES = [
  {
    key: "none",
    label: "No reshuffle",
    description:
      "Play the original shoe until there are too few cards to start another round, then end the game.",
  },
  {
    key: "shoe",
    label: "Traditional shoe",
    description:
      "Place a cut card 75%-81% into the shoe. Once that point is reached, finish the current round and shuffle a fresh shoe.",
  },
  {
    key: "continuous",
    label: "Continuous shuffler",
    description:
      "After every round, return the used cards and start the next round from a newly mixed full shoe.",
  },
  {
    key: "pitch",
    label: "Pitch game",
    description:
      "With one deck, reshuffle after every round. With two or more decks, reshuffle after roughly 50%-60% has been dealt.",
  },
];

const RESHUFFLE_STRATEGY_KEYS = new Set(
  RESHUFFLE_STRATEGIES.map((strategy) => strategy.key)
);

const SUITS = [
  { key: "spades", label: "♠", color: "black" },
  { key: "hearts", label: "♥", color: "red" },
  { key: "diamonds", label: "♦", color: "red" },
  { key: "clubs", label: "♣", color: "black" },
];

const SUIT_LABELS = SUITS.reduce((labels, suit) => {
  labels[suit.key] = suit.label;
  return labels;
}, {});

const RANKS = [
  { rank: "A", value: 11 },
  { rank: "2", value: 2 },
  { rank: "3", value: 3 },
  { rank: "4", value: 4 },
  { rank: "5", value: 5 },
  { rank: "6", value: 6 },
  { rank: "7", value: 7 },
  { rank: "8", value: 8 },
  { rank: "9", value: 9 },
  { rank: "10", value: 10 },
  { rank: "J", value: 10 },
  { rank: "Q", value: 10 },
  { rank: "K", value: 10 },
];

function toNumber(value, fallback = 0) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function formatPracticeCredits(value, maximumFractionDigits = 0) {
  const credits = new Intl.NumberFormat("en-US", {
    maximumFractionDigits,
  }).format(value);

  return `${credits} credits`;
}

function formatDateTime(value) {
  return new Intl.DateTimeFormat("en-US", {
    dateStyle: "medium",
    timeStyle: "medium",
  }).format(new Date(value));
}

function parseStakeSizes(value) {
  const sizes = String(value)
    .split(",")
    .map((item) => Math.round(toNumber(item.trim())))
    .filter((item) => item > 0);

  return Array.from(new Set(sizes)).sort((a, b) => a - b);
}

function getReshuffleStrategy(value) {
  return RESHUFFLE_STRATEGY_KEYS.has(value)
    ? value
    : DEFAULT_RESHUFFLE_STRATEGY;
}

function getReshuffleStrategyInfo(value) {
  return (
    RESHUFFLE_STRATEGIES.find(
      (strategy) => strategy.key === getReshuffleStrategy(value)
    ) || RESHUFFLE_STRATEGIES[0]
  );
}

function randomInteger(minimum, maximum) {
  return Math.floor(Math.random() * (maximum - minimum + 1)) + minimum;
}

function createReshufflePoint(deckCount, strategy) {
  const totalCards = deckCount * 52;

  if (strategy === "shoe") {
    return Math.round(totalCards * (randomInteger(75, 81) / 100));
  }

  if (strategy === "pitch" && deckCount > 1) {
    return Math.round(totalCards * (randomInteger(50, 60) / 100));
  }

  return null;
}

function createShoe(deckCount) {
  const cards = [];

  for (let deck = 1; deck <= deckCount; deck += 1) {
    SUITS.forEach((suit) => {
      RANKS.forEach((rank) => {
        cards.push({
          id: `${deck}-${suit.key}-${rank.rank}`,
          deck,
          suit: suit.key,
          suitLabel: suit.label,
          color: suit.color,
          rank: rank.rank,
          value: rank.value,
          label: `${rank.rank}${suit.label}`,
        });
      });
    });
  }

  return shuffle(cards);
}

function shuffle(cards) {
  const shuffled = [...cards];

  for (let index = shuffled.length - 1; index > 0; index -= 1) {
    const swapIndex = Math.floor(Math.random() * (index + 1));
    [shuffled[index], shuffled[swapIndex]] = [
      shuffled[swapIndex],
      shuffled[index],
    ];
  }

  return shuffled;
}

function summarizeCard(card) {
  if (!card) return null;

  return {
    rank: card.rank,
    suit: card.suit,
    label: getCardLabel(card),
    deck: card.deck,
  };
}

function getSuitLabel(card) {
  return SUIT_LABELS[card.suit] || card.suitLabel || "";
}

function getCardLabel(card) {
  if (!card) return "";
  return `${card.rank}${getSuitLabel(card)}`;
}

function summarizeCards(cards) {
  return cards.map(summarizeCard);
}

function scoreHand(cards) {
  let total = cards.reduce((sum, card) => sum + card.value, 0);
  let aces = cards.filter((card) => card.rank === "A").length;

  while (total > 21 && aces > 0) {
    total -= 10;
    aces -= 1;
  }

  return {
    total,
    soft: aces > 0,
    busted: total > 21,
  };
}

function isNaturalBlackjack(hand) {
  return (
    !hand.fromSplit &&
    hand.cards.length === 2 &&
    scoreHand(hand.cards).total === 21
  );
}

function canSplitHand(hand, balance, handCount) {
  return (
    hand.cards.length === 2 &&
    hand.cards[0].rank === hand.cards[1].rank &&
    balance >= hand.bet &&
    handCount < MAX_SPLIT_HANDS &&
    hand.status === "active"
  );
}

function canDoubleHand(hand, balance) {
  return (
    hand.cards.length === 2 && balance >= hand.bet && hand.status === "active"
  );
}

function canSurrenderHand(hand, hands) {
  return (
    hands.length === 1 &&
    hand.cards.length === 2 &&
    hand.status === "active" &&
    !hand.fromSplit
  );
}

function handLabel(status) {
  const labels = {
    active: "Playing",
    standing: "Standing",
    busted: "Busted",
    blackjack: "Blackjack",
    surrendered: "Surrendered",
  };

  return labels[status] || status;
}

function createHand(cards, bet, fromSplit = false, splitAces = false) {
  return {
    id: `hand-${Date.now()}-${Math.random().toString(16).slice(2)}`,
    cards,
    bet,
    fromSplit,
    splitAces,
    doubled: false,
    status: "active",
    result: null,
    payout: 0,
    actions: [],
  };
}

function drawCard(draft) {
  if (draft.shoe.length === 0) return null;
  return draft.shoe.shift();
}

function cardsDealtInCurrentShoe(draft) {
  return draft.settings.deckCount * 52 - draft.shoe.length;
}

function getReshufflePlan(draft) {
  const strategy = getReshuffleStrategy(draft.settings.reshuffleStrategy);
  const cardsDealt = cardsDealtInCurrentShoe(draft);

  if (!draft.reshufflePoint) {
    draft.reshufflePoint = createReshufflePoint(
      draft.settings.deckCount,
      strategy
    );
  }

  const reshufflePoint = draft.reshufflePoint;

  if (strategy === "continuous") {
    return {
      strategy,
      reason: "continuous_shuffle",
      message: "Continuous shuffler reset the shoe.",
    };
  }

  if (strategy === "pitch" && draft.settings.deckCount <= 1) {
    return {
      strategy,
      reason: "single_deck_pitch",
      message: "Single-deck pitch reshuffled after the round.",
    };
  }

  if (reshufflePoint && cardsDealt >= reshufflePoint) {
    return {
      strategy,
      reason: strategy === "pitch" ? "pitch_cut_card" : "shoe_cut_card",
      message:
        strategy === "pitch"
          ? "Pitch cut point reached; fresh cards are ready."
          : "Cut card reached; a fresh shoe is ready.",
    };
  }

  return null;
}

function reshuffleShoe(draft, plan) {
  const strategy = getReshuffleStrategy(draft.settings.reshuffleStrategy);

  draft.shoe = createShoe(draft.settings.deckCount);
  draft.shoeNumber = (draft.shoeNumber || 1) + 1;
  draft.reshufflePoint = createReshufflePoint(
    draft.settings.deckCount,
    strategy
  );

  addAction(draft, "reshuffle", {
    strategy,
    reason: plan.reason,
    shoe: draft.shoeNumber,
    nextReshufflePoint: draft.reshufflePoint,
  });
}

function nextPlayableHandIndex(hands, startIndex = 0) {
  for (let index = startIndex; index < hands.length; index += 1) {
    if (hands[index].status === "active" && !hands[index].splitAces) {
      return index;
    }
  }

  return -1;
}

function addAction(draft, type, details = {}) {
  const timestamp = new Date().toISOString();
  const dealerCards = draft.dealerHand
    ? draft.dealerHand.cards.map((card, index) =>
        draft.phase === "player" && index === 1
          ? { hidden: true }
          : summarizeCard(card)
      )
    : [];

  draft.actionLog.push({
    id: `${timestamp}-${draft.actionLog.length + 1}`,
    timestamp,
    round: draft.roundNumber,
    phase: draft.phase,
    type,
    balance: draft.balance,
    shoeRemaining: draft.shoe.length,
    dealerCards,
    playerHands: draft.playerHands.map((hand, index) => ({
      hand: index + 1,
      bet: hand.bet,
      cards: summarizeCards(hand.cards),
      value: scoreHand(hand.cards).total,
      status: hand.status,
      result: hand.result,
    })),
    details,
  });
}

function buildRoundSummary(draft, round, closingBalance, note) {
  const dealerScore = scoreHand(draft.dealerHand.cards);

  return {
    round: round.round,
    startedAt: round.startedAt,
    completedAt: new Date().toISOString(),
    openingBalance: round.openingBalance,
    closingBalance,
    initialBet: round.initialBet,
    stakeSize: round.stakeSize,
    stakeUnits: round.stakeUnits,
    dealerCard: summarizeCard(draft.dealerHand.cards[0]),
    dealerCards: summarizeCards(draft.dealerHand.cards),
    dealerValue: dealerScore.total,
    insurance: draft.insurance,
    playerHands: draft.playerHands.map((hand, index) => ({
      hand: index + 1,
      bet: hand.bet,
      doubled: hand.doubled,
      fromSplit: hand.fromSplit,
      splitAces: hand.splitAces,
      cards: summarizeCards(hand.cards),
      value: scoreHand(hand.cards).total,
      status: hand.status,
      result: hand.result,
      payout: hand.payout,
      actions: hand.actions,
    })),
    shoeRemaining: draft.shoe.length,
    note,
  };
}

function settleRound(draft, note = "Round complete") {
  let closingBalance = draft.balance;
  const dealerScore = scoreHand(draft.dealerHand.cards);
  const dealerBlackjack =
    draft.dealerHand.cards.length === 2 && dealerScore.total === 21;

  if (draft.insurance.taken) {
    if (dealerBlackjack) {
      const insuranceReturn = draft.insurance.amount * 3;
      closingBalance += insuranceReturn;
      draft.insurance.result = "won";
      draft.insurance.payout = insuranceReturn;
    } else {
      draft.insurance.result = "lost";
      draft.insurance.payout = 0;
    }
  }

  draft.playerHands = draft.playerHands.map((hand) => {
    const playerScore = scoreHand(hand.cards);
    let result = "lose";
    let payout = 0;

    if (hand.status === "surrendered") {
      result = "surrender";
      payout = hand.bet / 2;
    } else if (playerScore.busted) {
      result = "bust";
      payout = 0;
    } else if (dealerBlackjack) {
      result = isNaturalBlackjack(hand) ? "push" : "lose";
      payout = result === "push" ? hand.bet : 0;
    } else if (isNaturalBlackjack(hand)) {
      result = "blackjack";
      payout = hand.bet * 2.5;
    } else if (dealerScore.busted) {
      result = "win";
      payout = hand.bet * 2;
    } else if (playerScore.total > dealerScore.total) {
      result = "win";
      payout = hand.bet * 2;
    } else if (playerScore.total === dealerScore.total) {
      result = "push";
      payout = hand.bet;
    }

    closingBalance += payout;

    return {
      ...hand,
      result,
      payout,
      status:
        hand.status === "active" && result === "blackjack"
          ? "blackjack"
          : hand.status,
    };
  });

  const reshufflePlan = getReshufflePlan(draft);
  const shoeCannotContinue =
    !reshufflePlan && draft.shoe.length < MIN_CARDS_TO_START_ROUND;

  draft.balance = Math.round(closingBalance * 100) / 100;
  const summary = buildRoundSummary(
    draft,
    draft.currentRound,
    draft.balance,
    note
  );
  draft.rounds.push(summary);
  draft.currentRound = null;

  draft.phase =
    draft.balance <= 0 || shoeCannotContinue ? "game-over" : "round-over";
  draft.message =
    draft.balance <= 0
      ? "Your practice credits are out."
      : shoeCannotContinue
        ? "The shoe has too few cards to start another round."
        : reshufflePlan
          ? `${note} ${reshufflePlan.message}`
          : note;

  addAction(draft, "round_settled", { note });

  if (draft.phase !== "game-over" && reshufflePlan) {
    reshuffleShoe(draft, reshufflePlan);
  }

  if (draft.phase === "game-over") {
    draft.endedAt = new Date().toISOString();
  }
}

function dealerPlayAndSettle(draft) {
  const hasLiveHands = draft.playerHands.some((hand) => {
    const score = scoreHand(hand.cards);
    return hand.status !== "surrendered" && !score.busted;
  });

  if (hasLiveHands) {
    let dealerScore = scoreHand(draft.dealerHand.cards);
    while (dealerScore.total < 17) {
      const card = drawCard(draft);
      if (!card) {
        draft.phase = "game-over";
        draft.message = "The shoe is empty.";
        draft.endedAt = new Date().toISOString();
        addAction(draft, "shoe_empty", { during: "dealer_draw" });
        return;
      }
      draft.dealerHand.cards.push(card);
      addAction(draft, "dealer_hit", { card: summarizeCard(card) });
      dealerScore = scoreHand(draft.dealerHand.cards);
    }
  }

  settleRound(draft);
}

function finishHandOrDealer(draft, nextIndex) {
  const nextIndexToPlay = nextPlayableHandIndex(draft.playerHands, nextIndex);
  if (nextIndexToPlay >= 0) {
    draft.activeHandIndex = nextIndexToPlay;
    return;
  }

  dealerPlayAndSettle(draft);
}

function createGame(setup) {
  const stakeSizes = parseStakeSizes(setup.stakeSizes);
  const deckCount = Math.max(
    1,
    Math.min(Math.round(toNumber(setup.deckCount, 1)), 8)
  );
  const initialBalance = Math.max(
    Math.round(toNumber(setup.initialBalance, 1000)),
    1
  );
  const stakeSize = stakeSizes.includes(Math.round(toNumber(setup.stakeSize)))
    ? Math.round(toNumber(setup.stakeSize))
    : stakeSizes[0] || 100;
  const stakeUnits = Math.max(
    1,
    Math.min(Math.round(toNumber(setup.stakeUnits, 1)), 20)
  );
  const reshuffleStrategy = getReshuffleStrategy(setup.reshuffleStrategy);

  return {
    version: 1,
    sessionId: `blackjack-${Date.now()}`,
    startedAt: new Date().toISOString(),
    endedAt: null,
    settings: {
      initialBalance,
      deckCount,
      stakeSizes: stakeSizes.length ? stakeSizes : [100, 200, 500, 1000],
      stakeSize,
      stakeUnits,
      reshuffleStrategy,
      dealerRule: "stand-soft-17",
      blackjackPayout: "3:2",
      maxSplitHands: MAX_SPLIT_HANDS,
    },
    phase: "betting",
    balance: initialBalance,
    roundNumber: 0,
    shoe: createShoe(deckCount),
    shoeNumber: 1,
    reshufflePoint: createReshufflePoint(deckCount, reshuffleStrategy),
    playerHands: [],
    dealerHand: null,
    activeHandIndex: 0,
    insurance: {
      offered: false,
      taken: false,
      amount: 0,
      result: null,
      payout: 0,
    },
    currentRound: null,
    rounds: [],
    actionLog: [],
    message: "Choose a practice amount and deal.",
  };
}

function cloneGame(game) {
  return JSON.parse(JSON.stringify(game));
}

function Card({ card, hidden = false }) {
  if (hidden) {
    return (
      <span
        className="blackjack-card blackjack-card--hidden"
        aria-label="Hidden card"
      >
        ?
      </span>
    );
  }

  return (
    <span className={`blackjack-card blackjack-card--${card.color}`}>
      <span>{card.rank}</span>
      <span>{getSuitLabel(card)}</span>
    </span>
  );
}

function Metric({ label, value, tone }) {
  return (
    <div
      className={`blackjack-app__metric ${tone ? `blackjack-app__metric--${tone}` : ""}`}
    >
      <span>{label}</span>
      <strong>{value}</strong>
    </div>
  );
}

function BlackjackGame() {
  const [setup, setSetup] = useState(DEFAULT_SETUP);
  const [game, setGame] = useState(null);
  const [selectedStake, setSelectedStake] = useState(DEFAULT_SETUP.stakeSize);
  const [selectedUnits, setSelectedUnits] = useState(DEFAULT_SETUP.stakeUnits);
  const [disclaimerAccepted, setDisclaimerAccepted] = useState(false);

  useEffect(() => {
    document.title = "Blackjack Practice Simulator — Xuan Cao";
    const saved = window.localStorage.getItem(STORAGE_KEY);
    if (!saved) return;

    try {
      const parsed = JSON.parse(saved);
      setGame(parsed);
      setSelectedStake(parsed.settings.stakeSize);
      setSelectedUnits(parsed.settings.stakeUnits);
    } catch (error) {
      console.error("Failed to restore blackjack game:", error);
    }
  }, []);

  useEffect(() => {
    if (game) {
      window.localStorage.setItem(STORAGE_KEY, JSON.stringify(game));
    }
  }, [game]);

  const setupStakeSizes = useMemo(
    () => parseStakeSizes(setup.stakeSizes),
    [setup.stakeSizes]
  );
  const setupReshuffleStrategy = getReshuffleStrategy(setup.reshuffleStrategy);
  const gameReshuffleStrategy = game
    ? getReshuffleStrategyInfo(game.settings?.reshuffleStrategy)
    : null;

  const activeHand = game?.playerHands[game.activeHandIndex] || null;
  const activeHandScore = activeHand ? scoreHand(activeHand.cards) : null;
  const dealerScore = game?.dealerHand
    ? scoreHand(game.dealerHand.cards)
    : null;
  const cardsPlayed = game
    ? game.settings.deckCount * 52 - game.shoe.length
    : 0;
  const currentBet = selectedStake * selectedUnits;
  const exportData = useMemo(() => {
    if (!game) return null;
    const { shoe, ...rest } = game;
    return {
      ...rest,
      shoe: {
        deckCount: game.settings.deckCount,
        totalCards: game.settings.deckCount * 52,
        remainingCards: shoe.length,
        playedCards: game.settings.deckCount * 52 - shoe.length,
      },
    };
  }, [game]);

  const updateSetup = (key, value) => {
    setSetup((current) => ({
      ...current,
      [key]: value,
    }));
  };

  const mutateGame = (mutator) => {
    setGame((current) => {
      if (!current) return current;
      const draft = cloneGame(current);
      mutator(draft);
      return draft;
    });
  };

  const startGame = (event) => {
    event.preventDefault();
    if (!disclaimerAccepted) return;

    const nextGame = createGame(setup);
    setSelectedStake(nextGame.settings.stakeSize);
    setSelectedUnits(nextGame.settings.stakeUnits);
    addAction(nextGame, "game_started", {
      settings: nextGame.settings,
    });
    setGame(nextGame);
  };

  const resetGame = () => {
    window.localStorage.removeItem(STORAGE_KEY);
    setGame(null);
    setSetup(DEFAULT_SETUP);
    setSelectedStake(DEFAULT_SETUP.stakeSize);
    setSelectedUnits(DEFAULT_SETUP.stakeUnits);
  };

  const placeBet = () => {
    mutateGame((draft) => {
      const bet = selectedStake * selectedUnits;
      if (draft.phase !== "betting" || bet <= 0 || bet > draft.balance) return;
      if (draft.shoe.length < MIN_CARDS_TO_START_ROUND) {
        draft.phase = "game-over";
        draft.message = "The shoe has too few cards to start another round.";
        draft.endedAt = new Date().toISOString();
        addAction(draft, "shoe_empty", { during: "deal" });
        return;
      }

      draft.roundNumber += 1;
      draft.balance -= bet;
      draft.phase = "player";
      draft.dealerHand = { cards: [] };
      draft.playerHands = [createHand([], bet)];
      draft.activeHandIndex = 0;
      draft.insurance = {
        offered: false,
        taken: false,
        amount: 0,
        result: null,
        payout: 0,
      };
      draft.currentRound = {
        round: draft.roundNumber,
        startedAt: new Date().toISOString(),
        openingBalance: draft.balance + bet,
        initialBet: bet,
        stakeSize: selectedStake,
        stakeUnits: selectedUnits,
      };

      draft.playerHands[0].cards.push(drawCard(draft));
      draft.dealerHand.cards.push(drawCard(draft));
      draft.playerHands[0].cards.push(drawCard(draft));
      draft.dealerHand.cards.push(drawCard(draft));

      addAction(draft, "deal", { bet });

      const dealerUpCard = draft.dealerHand.cards[0];
      const dealerHasBlackjack = scoreHand(draft.dealerHand.cards).total === 21;
      const playerHasBlackjack = isNaturalBlackjack(draft.playerHands[0]);

      if (dealerUpCard.rank === "A") {
        draft.phase = "insurance";
        draft.insurance.offered = true;
        draft.message = "Dealer shows an ace.";
        addAction(draft, "insurance_offered", {
          maximum: bet / 2,
        });
      } else if (dealerHasBlackjack || playerHasBlackjack) {
        if (playerHasBlackjack) {
          draft.playerHands[0].status = "blackjack";
        }
        settleRound(
          draft,
          dealerHasBlackjack ? "Dealer has blackjack." : "Player blackjack."
        );
      } else {
        draft.message = "Play your hand.";
      }
    });
  };

  const resolveInsurance = (takeInsurance) => {
    mutateGame((draft) => {
      if (draft.phase !== "insurance") return;

      const insuranceAmount = draft.currentRound.initialBet / 2;
      if (takeInsurance && draft.balance >= insuranceAmount) {
        draft.balance -= insuranceAmount;
        draft.insurance.taken = true;
        draft.insurance.amount = insuranceAmount;
        addAction(draft, "insurance_taken", { amount: insuranceAmount });
      } else {
        addAction(draft, "insurance_declined");
      }

      draft.phase = "player";
      const dealerHasBlackjack = scoreHand(draft.dealerHand.cards).total === 21;
      const playerHasBlackjack = isNaturalBlackjack(draft.playerHands[0]);

      if (dealerHasBlackjack || playerHasBlackjack) {
        if (playerHasBlackjack) {
          draft.playerHands[0].status = "blackjack";
        }
        settleRound(
          draft,
          dealerHasBlackjack ? "Dealer has blackjack." : "Player blackjack."
        );
      } else {
        draft.message = "Play your hand.";
      }
    });
  };

  const hit = () => {
    mutateGame((draft) => {
      if (draft.phase !== "player") return;
      const hand = draft.playerHands[draft.activeHandIndex];
      if (!hand || hand.status !== "active") return;

      const card = drawCard(draft);
      if (!card) {
        draft.phase = "game-over";
        draft.message = "The shoe is empty.";
        draft.endedAt = new Date().toISOString();
        addAction(draft, "shoe_empty", { during: "player_hit" });
        return;
      }

      hand.cards.push(card);
      hand.actions.push({
        type: "hit",
        card: summarizeCard(card),
        at: new Date().toISOString(),
      });
      addAction(draft, "hit", {
        hand: draft.activeHandIndex + 1,
        card: summarizeCard(card),
      });

      const score = scoreHand(hand.cards);
      if (score.busted) {
        hand.status = "busted";
        finishHandOrDealer(draft, draft.activeHandIndex + 1);
      } else if (score.total === 21) {
        hand.status = "standing";
        finishHandOrDealer(draft, draft.activeHandIndex + 1);
      }
    });
  };

  const stand = () => {
    mutateGame((draft) => {
      if (draft.phase !== "player") return;
      const hand = draft.playerHands[draft.activeHandIndex];
      if (!hand || hand.status !== "active") return;

      hand.status = "standing";
      hand.actions.push({ type: "stand", at: new Date().toISOString() });
      addAction(draft, "stand", { hand: draft.activeHandIndex + 1 });
      finishHandOrDealer(draft, draft.activeHandIndex + 1);
    });
  };

  const doubleDown = () => {
    mutateGame((draft) => {
      if (draft.phase !== "player") return;
      const hand = draft.playerHands[draft.activeHandIndex];
      if (!hand || !canDoubleHand(hand, draft.balance)) return;

      draft.balance -= hand.bet;
      hand.bet *= 2;
      hand.doubled = true;

      const card = drawCard(draft);
      if (!card) {
        draft.phase = "game-over";
        draft.message = "The shoe is empty.";
        draft.endedAt = new Date().toISOString();
        addAction(draft, "shoe_empty", { during: "double_down" });
        return;
      }

      hand.cards.push(card);
      const score = scoreHand(hand.cards);
      hand.status = score.busted ? "busted" : "standing";
      hand.actions.push({
        type: "double",
        card: summarizeCard(card),
        at: new Date().toISOString(),
      });
      addAction(draft, "double", {
        hand: draft.activeHandIndex + 1,
        card: summarizeCard(card),
        newBet: hand.bet,
      });
      finishHandOrDealer(draft, draft.activeHandIndex + 1);
    });
  };

  const split = () => {
    mutateGame((draft) => {
      if (draft.phase !== "player") return;
      const hand = draft.playerHands[draft.activeHandIndex];
      if (!hand || !canSplitHand(hand, draft.balance, draft.playerHands.length))
        return;

      const firstCard = hand.cards[0];
      const secondCard = hand.cards[1];
      const splitAces = firstCard.rank === "A";
      const firstDraw = drawCard(draft);
      const secondDraw = drawCard(draft);

      if (!firstDraw || !secondDraw) {
        draft.phase = "game-over";
        draft.message = "The shoe is empty.";
        draft.endedAt = new Date().toISOString();
        addAction(draft, "shoe_empty", { during: "split" });
        return;
      }

      draft.balance -= hand.bet;
      const handOne = createHand(
        [firstCard, firstDraw],
        hand.bet,
        true,
        splitAces
      );
      const handTwo = createHand(
        [secondCard, secondDraw],
        hand.bet,
        true,
        splitAces
      );
      handOne.actions = [
        ...hand.actions,
        {
          type: "split",
          card: summarizeCard(firstDraw),
          at: new Date().toISOString(),
        },
      ];
      handTwo.actions = [
        {
          type: "split",
          card: summarizeCard(secondDraw),
          at: new Date().toISOString(),
        },
      ];

      if (splitAces) {
        handOne.status = "standing";
        handTwo.status = "standing";
      }

      draft.playerHands.splice(draft.activeHandIndex, 1, handOne, handTwo);
      addAction(draft, "split", {
        hand: draft.activeHandIndex + 1,
        cards: [summarizeCard(firstDraw), summarizeCard(secondDraw)],
      });

      if (splitAces) {
        finishHandOrDealer(draft, draft.activeHandIndex + 2);
      }
    });
  };

  const surrender = () => {
    mutateGame((draft) => {
      if (draft.phase !== "player") return;
      const hand = draft.playerHands[draft.activeHandIndex];
      if (!hand || !canSurrenderHand(hand, draft.playerHands)) return;

      hand.status = "surrendered";
      hand.actions.push({ type: "surrender", at: new Date().toISOString() });
      addAction(draft, "surrender", { hand: draft.activeHandIndex + 1 });
      dealerPlayAndSettle(draft);
    });
  };

  const nextRound = () => {
    mutateGame((draft) => {
      if (draft.phase !== "round-over") return;
      draft.phase =
        draft.balance <= 0 || draft.shoe.length < MIN_CARDS_TO_START_ROUND
          ? "game-over"
          : "betting";
      draft.playerHands = [];
      draft.dealerHand = null;
      draft.activeHandIndex = 0;
      draft.message = "Choose a stake and deal.";
      addAction(draft, "next_round");
    });
  };

  const downloadJson = () => {
    if (!exportData) return;
    const blob = new Blob([JSON.stringify(exportData, null, 2)], {
      type: "application/json",
    });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `${game.sessionId}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const clearHistory = () => {
    if (!game) return;
    mutateGame((draft) => {
      draft.rounds = [];
      draft.actionLog = [];
      addAction(draft, "history_cleared");
    });
  };

  if (!game) {
    return (
      <div className="blackjack-app">
        <div className="container container--wide">
          <header className="blackjack-app__header fade-in">
            <div>
              <p className="section-label">Educational simulator</p>
              <h1 className="page-title">Blackjack Practice Simulator</h1>
              <p className="page-subtitle">
                Study blackjack rules with free practice credits, configurable
                deck settings, and a local hand history. No real money or prizes
                are involved.
              </p>
            </div>
            <div className="blackjack-app__rule-note">
              Educational demo only. No deposits, withdrawals, wagering,
              gambling services, or financial rewards are offered. Rule model:
              3:2 blackjack, insurance, split, double down, surrender, dealer
              stands on soft 17.
            </div>
          </header>

          <form
            className="blackjack-app__setup fade-in fade-in--delay-1"
            onSubmit={startGame}
          >
            <label>
              <span>Initial practice credits</span>
              <input
                type="number"
                min="1"
                step="1"
                value={setup.initialBalance}
                onChange={(event) =>
                  updateSetup("initialBalance", event.target.value)
                }
              />
            </label>
            <label>
              <span>Deck count</span>
              <input
                type="number"
                min="1"
                max="8"
                step="1"
                value={setup.deckCount}
                onChange={(event) =>
                  updateSetup("deckCount", event.target.value)
                }
              />
            </label>
            <label>
              <span>Practice amount options</span>
              <input
                type="text"
                value={setup.stakeSizes}
                onChange={(event) =>
                  updateSetup("stakeSizes", event.target.value)
                }
              />
            </label>
            <label>
              <span>Default practice amount</span>
              <select
                value={setup.stakeSize}
                onChange={(event) =>
                  updateSetup("stakeSize", event.target.value)
                }
              >
                {(setupStakeSizes.length ? setupStakeSizes : [100]).map(
                  (size) => (
                    <option key={size} value={size}>
                      {formatPracticeCredits(size)}
                    </option>
                  )
                )}
              </select>
            </label>
            <label>
              <span>Default unit count</span>
              <input
                type="number"
                min="1"
                max="20"
                step="1"
                value={setup.stakeUnits}
                onChange={(event) =>
                  updateSetup("stakeUnits", event.target.value)
                }
              />
            </label>
            <fieldset className="blackjack-app__reshuffle">
              <legend>Reshuffle strategy</legend>
              <div className="blackjack-app__reshuffle-options">
                {RESHUFFLE_STRATEGIES.map((strategy) => (
                  <label
                    key={strategy.key}
                    className={`blackjack-app__reshuffle-option ${
                      setupReshuffleStrategy === strategy.key ? "is-active" : ""
                    }`}
                  >
                    <input
                      type="radio"
                      name="reshuffleStrategy"
                      value={strategy.key}
                      checked={setupReshuffleStrategy === strategy.key}
                      onChange={(event) =>
                        updateSetup("reshuffleStrategy", event.target.value)
                      }
                    />
                    <span>{strategy.label}</span>
                    <small>{strategy.description}</small>
                  </label>
                ))}
              </div>
            </fieldset>
            <label className="blackjack-app__disclaimer">
              <input
                type="checkbox"
                checked={disclaimerAccepted}
                onChange={(event) =>
                  setDisclaimerAccepted(event.target.checked)
                }
                required
              />
              <div className="blackjack-app__disclaimer-text">
                By checking this box, I acknowledge and agree that:
                <ol>
                  <li>
                    1. This blackjack practice simulator is provided solely for
                    educational and informational purposes.
                  </li>
                  <li>
                    2. No real money, prizes, wagering, deposits, withdrawals, or
                    gambling services are offered, and participation does not
                    create any financial entitlement.
                  </li>
                  <li>
                    3. This simulator is not intended to represent, replicate, or
                    model the rules, odds, payout structures, operations, or
                    outcomes of any real-world gambling game, casino game, or
                    gambling service.
                  </li>
                  <li>
                    4. Nothing in this simulator constitutes gambling advice,
                    gaming strategy advice, financial advice, legal advice, or
                    any recommendation to participate in gambling activity.
                  </li>
                  <li>
                    5. This simulator does not promote, endorse, or encourage
                    gambling activity.
                  </li>
                  <li>
                    6. I am solely responsible for ensuring that my use complies
                    with all applicable laws, regulations, and age eligibility
                    requirements in my jurisdiction.
                  </li>
                  <li>
                    7. If you have any questions or concerns, please feel free to contact me at contact@xuancao.ca
                  </li>
                </ol>
              </div>
            </label>
            <button type="submit" disabled={!disclaimerAccepted}>
              Start practice simulator
            </button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="blackjack-app">
      <div className="container container--wide">
        <header className="blackjack-app__header fade-in">
          <div>
            <p className="section-label">Educational simulator</p>
            <h1 className="page-title">Blackjack Practice Simulator</h1>
            <p className="page-subtitle">
              Session settings are locked for consistent practice. Free practice
              credits, the shoe, and action history stay in browser memory until
              a new practice session is started.
            </p>
          </div>
          <div className="blackjack-app__session">
            <span>Started {formatDateTime(game.startedAt)}</span>
            <span>Reshuffle {gameReshuffleStrategy.label}</span>
            <button type="button" onClick={resetGame}>
              New practice session
            </button>
          </div>
        </header>

        <section className="blackjack-app__metrics fade-in fade-in--delay-1">
          <Metric
            label="Practice credits"
            value={formatPracticeCredits(game.balance)}
            tone={game.balance > game.settings.initialBalance ? "positive" : ""}
          />
          <Metric label="Round" value={game.roundNumber || 0} />
          <Metric
            label="Cards played"
            value={`${cardsPlayed} / ${game.settings.deckCount * 52}`}
          />
          <Metric label="Shoe left" value={game.shoe.length} />
        </section>

        <section className="blackjack-app__workspace fade-in fade-in--delay-2">
          <div className="blackjack-app__table">
            <div className="blackjack-app__dealer">
              <div className="blackjack-app__hand-heading">
                <h2>Dealer</h2>
                <span>
                  {game.dealerHand &&
                  game.phase !== "player" &&
                  game.phase !== "insurance"
                    ? dealerScore.total
                    : game.dealerHand
                      ? scoreHand([game.dealerHand.cards[0]]).total
                      : "-"}
                </span>
              </div>
              <div className="blackjack-app__cards">
                {game.dealerHand ? (
                  game.dealerHand.cards.map((card, index) => (
                    <Card
                      key={card.id}
                      card={card}
                      hidden={
                        (game.phase === "player" ||
                          game.phase === "insurance") &&
                        index === 1
                      }
                    />
                  ))
                ) : (
                  <span className="blackjack-app__empty-card">No cards</span>
                )}
              </div>
            </div>

            <div className="blackjack-app__status" role="status">
              {game.message}
            </div>

            <div className="blackjack-app__hands">
              {game.playerHands.length ? (
                game.playerHands.map((hand, index) => {
                  const score = scoreHand(hand.cards);
                  const active =
                    game.phase === "player" && index === game.activeHandIndex;

                  return (
                    <article
                      key={hand.id}
                      className={`blackjack-app__player-hand ${active ? "is-active" : ""}`}
                    >
                      <div className="blackjack-app__hand-heading">
                        <h2>Hand {index + 1}</h2>
                        <span>
                          {score.total}
                          {score.soft ? " soft" : ""}
                        </span>
                      </div>
                      <div className="blackjack-app__cards">
                        {hand.cards.map((card) => (
                          <Card key={card.id} card={card} />
                        ))}
                      </div>
                      <dl className="blackjack-app__hand-meta">
                        <div>
                          <dt>Practice amount</dt>
                          <dd>{formatPracticeCredits(hand.bet)}</dd>
                        </div>
                        <div>
                          <dt>Status</dt>
                          <dd>{handLabel(hand.status)}</dd>
                        </div>
                        <div>
                          <dt>Result</dt>
                          <dd>{hand.result || "-"}</dd>
                        </div>
                        <div>
                          <dt>Practice return</dt>
                          <dd>
                            {hand.payout
                              ? formatPracticeCredits(hand.payout)
                              : "-"}
                          </dd>
                        </div>
                      </dl>
                    </article>
                  );
                })
              ) : (
                <div className="blackjack-app__empty-hand">
                  Choose a practice amount to deal.
                </div>
              )}
            </div>
          </div>

          <aside className="blackjack-app__controls">
            {game.phase === "betting" && (
              <section className="blackjack-app__panel">
                <div className="blackjack-app__panel-header">
                  <h2>Practice amount</h2>
                  <p>{formatPracticeCredits(currentBet)}</p>
                </div>
                <div className="blackjack-app__stake-grid">
                  {game.settings.stakeSizes.map((size) => (
                    <button
                      type="button"
                      key={size}
                      className={selectedStake === size ? "is-active" : ""}
                      onClick={() => setSelectedStake(size)}
                    >
                      {formatPracticeCredits(size)}
                    </button>
                  ))}
                </div>
                <label className="blackjack-app__units">
                  <span>Unit count</span>
                  <input
                    type="number"
                    min="1"
                    max="20"
                    step="1"
                    value={selectedUnits}
                    onChange={(event) =>
                      setSelectedUnits(
                        Math.max(1, Math.round(toNumber(event.target.value, 1)))
                      )
                    }
                  />
                </label>
                <button
                  type="button"
                  className="blackjack-app__primary"
                  onClick={placeBet}
                  disabled={currentBet <= 0 || currentBet > game.balance}
                >
                  Deal
                </button>
              </section>
            )}

            {game.phase === "insurance" && (
              <section className="blackjack-app__panel">
                <div className="blackjack-app__panel-header">
                  <h2>Insurance</h2>
                  <p>
                    {formatPracticeCredits(game.currentRound.initialBet / 2)}
                  </p>
                </div>
                <button
                  type="button"
                  className="blackjack-app__primary"
                  onClick={() => resolveInsurance(true)}
                  disabled={game.balance < game.currentRound.initialBet / 2}
                >
                  Take insurance
                </button>
                <button type="button" onClick={() => resolveInsurance(false)}>
                  Decline
                </button>
              </section>
            )}

            {game.phase === "player" && activeHand && (
              <section className="blackjack-app__panel">
                <div className="blackjack-app__panel-header">
                  <h2>Hand {game.activeHandIndex + 1}</h2>
                  <p>
                    {activeHandScore.total}
                    {activeHandScore.soft ? " soft" : ""}
                  </p>
                </div>
                <div className="blackjack-app__action-grid">
                  <button type="button" onClick={hit}>
                    Hit
                  </button>
                  <button type="button" onClick={stand}>
                    Stand
                  </button>
                  <button
                    type="button"
                    onClick={doubleDown}
                    disabled={!canDoubleHand(activeHand, game.balance)}
                  >
                    Double
                  </button>
                  <button
                    type="button"
                    onClick={split}
                    disabled={
                      !canSplitHand(
                        activeHand,
                        game.balance,
                        game.playerHands.length
                      )
                    }
                  >
                    Split
                  </button>
                  <button
                    type="button"
                    onClick={surrender}
                    disabled={!canSurrenderHand(activeHand, game.playerHands)}
                  >
                    Surrender
                  </button>
                </div>
              </section>
            )}

            {(game.phase === "round-over" || game.phase === "game-over") && (
              <section className="blackjack-app__panel">
                <div className="blackjack-app__panel-header">
                  <h2>
                    {game.phase === "game-over"
                      ? "Practice session over"
                      : "Round closed"}
                  </h2>
                  <p>{formatPracticeCredits(game.balance)}</p>
                </div>
                {game.phase === "round-over" ? (
                  <button
                    type="button"
                    className="blackjack-app__primary"
                    onClick={nextRound}
                  >
                    Next round
                  </button>
                ) : (
                  <button
                    type="button"
                    className="blackjack-app__primary"
                    onClick={resetGame}
                  >
                    Start new practice session
                  </button>
                )}
              </section>
            )}

            <section className="blackjack-app__panel">
              <div className="blackjack-app__panel-header">
                <h2>History</h2>
                <p>{game.actionLog.length} actions</p>
              </div>
              <div className="blackjack-app__history-actions">
                <button type="button" onClick={downloadJson}>
                  Download JSON
                </button>
                <button type="button" onClick={clearHistory}>
                  Clear log
                </button>
              </div>
            </section>
          </aside>
        </section>

        <section className="blackjack-app__panel blackjack-app__history-panel fade-in fade-in--delay-3">
          <div className="blackjack-app__panel-header">
            <h2>Round Log</h2>
            <p>{game.rounds.length} completed</p>
          </div>
          <div className="blackjack-app__table-wrap">
            <table className="blackjack-app__rounds">
              <thead>
                <tr>
                  <th>Round</th>
                  <th>Practice amount</th>
                  <th>Dealer cards</th>
                  <th>Player cards</th>
                  <th>Result</th>
                  <th>Practice credits</th>
                </tr>
              </thead>
              <tbody>
                {game.rounds.length ? (
                  game.rounds.slice(-12).map((round) => (
                    <tr key={`${round.round}-${round.completedAt}`}>
                      <td>{round.round}</td>
                      <td>{formatPracticeCredits(round.initialBet)}</td>
                      <td>
                        {(round.dealerCards || [round.dealerCard])
                          .filter(Boolean)
                          .map((card) => getCardLabel(card))
                          .join(" ") || "-"}
                      </td>
                      <td>
                        {round.playerHands
                          .map((hand) =>
                            hand.cards
                              .map((card) => getCardLabel(card))
                              .join(" ")
                          )
                          .join(" / ")}
                      </td>
                      <td>
                        {round.playerHands
                          .map((hand) => hand.result)
                          .join(" / ")}
                      </td>
                      <td>{formatPracticeCredits(round.closingBalance)}</td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan="6">No completed rounds yet.</td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </section>
      </div>
    </div>
  );
}

export default BlackjackGame;
